if (-not [string]::IsNullOrWhiteSpace($env:CARGO_BUILD_BUILD_DIR)) {
    throw 'CARGO_BUILD_BUILD_DIR override detected; refuse potentially separate intermediate cache.'
}

foreach ($argument in $CargoArguments) {
